H.background();
const w = H.W, h = H.H;
const a = Math.max(2, Math.round(P.base));
const m = Math.max(0, Math.round(P.m));
const n = Math.max(0, Math.round(P.n));
const total = m + n;
const cell = 26, gap = 6;
const baseX = 60, baseY = h * 0.5;
H.text("Product rule:  a^m · a^n = a^(m+n)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a = " + a + ",   " + a + "^" + m + " · " + a + "^" + n + " = " + a + "^" + total + " = " + Math.pow(a, total), 24, 52, { color: H.colors.sub, size: 13 });
// sweep highlights one factor box at a time, looping over all total boxes
const sweep = total > 0 ? Math.floor((t * 1.5) % total) : -1;
function drawGroup(x0, count, col, lbl) {
  for (let i = 0; i < count; i++) {
    const gx = x0 + i * (cell + gap);
    const isLit = (lbl === "left" && i === sweep) || (lbl === "right" && (i + m) === sweep);
    H.rect(gx, baseY, cell, cell, { fill: isLit ? H.colors.warn : col, stroke: H.colors.ink, width: 1.5, radius: 4 });
    H.text("a", gx + cell * 0.5, baseY + cell * 0.5 + 5, { color: H.colors.bg, size: 14, weight: 700, align: "center" });
  }
  return x0 + count * (cell + gap);
}
const midX = drawGroup(baseX, m, H.colors.accent, "left");
H.text("×", midX + 2, baseY + cell * 0.5 + 6, { color: H.colors.ink, size: 20, weight: 700 });
drawGroup(midX + 22, n, H.colors.accent2, "right");
H.text(a + "^" + m + " = " + m + " factors of a", baseX, baseY - 18, { color: H.colors.accent, size: 13 });
H.text(a + "^" + n + " = " + n + " factors", midX + 22, baseY - 18, { color: H.colors.accent2, size: 13 });
H.text("Counting factors:  " + m + " + " + n + " = " + total + "  →  exponents ADD", baseX, baseY + 70, { color: H.colors.good, size: 14, weight: 600 });
H.legend([{ label: "a^m factors", color: H.colors.accent }, { label: "a^n factors", color: H.colors.accent2 }], w - 170, 30);
